Lemma PUSHC (ix : list nat) M1 model1 LK1 Aw1 st1 en1 k1 b1 e1 cr1 kbb1 (fx1 fx2 : FPState) R1 R2 (pc0 ra ch : Z) (M2v : mem) (Wp : Z -> Prop) :
